    /** @param array<string,mixed>$payload */ private function outputs(string$o,string$p,string$u,string$type,string$id,string$title,string$status,array$payload):void{$this->record($o,$p,$u,$type,$title,$status,$payload,[$id]);$this->audit($o,$u,'practice.'.$type.'_created',$type,$id,$payload);if(in_array($status,['requires_review','blocked'],true))$this->recommend($o,$p,$type,$id,'Review '.$title,implode('; ',$payload['blockers']??[])?:'Workflow state requires a human decision.','high');}
    /** @param array<string,mixed>$payload @param list<string>$links */ private function record(string$o,string$p,string$u,string$type,string$title,string$status,array$payload,array$links):void{$normal=match($status){'draft'=>'draft','approved','won','signed_off'=>'approved','rejected','lost','abandoned'=>'rejected','superseded'=>'superseded',default=>'pending_review'};$this->pdo->prepare("INSERT INTO project_records(id,organisation_id,project_id,phase,module_key,record_type,title,status,payload,approvals,linked_record_ids,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'practice_management',:module,:type,:title,:status,:payload,'{\"required\":false}',:links,UNHEX(:u))")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'module'=>self::MODULE,'type'=>$type,'title'=>substr($title,0,220),'status'=>$normal,'payload'=>$this->json(['workflowStatus'=>$status]+$payload),'links'=>$this->json($links),'u'=>$u]);}
    /** @param array<string,mixed>$payload */ private function inbox(string$o,?string$p,string$type,string$title,string$detail,string$priority,array$payload):void{$this->pdo->prepare("INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'member',:type,:title,:detail,:priority,:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'type'=>$type,'title'=>substr($title,0,220),'detail'=>substr($detail,0,1000),'priority'=>$priority,'payload'=>$this->json($payload)]);}
    private function recommend(string$o,string$p,string$type,string$id,string$title,string$rationale,string$severity):void{$this->pdo->prepare("INSERT INTO practice_agent_recommendations(id,organisation_id,project_id,source_type,source_object_id,title,rationale,severity,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:type,UNHEX(:source),:title,:rationale,:severity,'open')")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'type'=>$type,'source'=>$id,'title'=>$title,'rationale'=>$rationale,'severity'=>$severity]);}
    /** @param array<string,mixed>$metadata */ private function audit(string$o,string$u,string$action,string$type,string$id,array$metadata):void{(new AuditService($this->pdo))->append($o,$u,$action,$type,$id,$metadata);}
    /** @param list<string>$json @return array<string,mixed> */ private function one(string$table,string$o,string$p,string$id,array$json):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new PracticeException('practice_record_not_found');foreach($json as$c)$r[$c]=$this->decode($r[$c]);return$this->camel($r);}
    /** @param list<string>$json @return list<array<string,mixed>> */ private function all(string$table,string$o,string$p,array$json):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at,id");$s->execute(['o'=>$o,'p'=>$p]);$out=[];foreach($s->fetchAll()as$r){foreach($json as$c)$r[$c]=$this->decode($r[$c]);$out[]=$this->camel($r);}return$out;}
    /** @return list<array<string,mixed>> */ private function registrations(string$o):array{$s=$this->pdo->prepare('SELECT *,LOWER(HEX(id)) id FROM practice_registration_renewals WHERE organisation_id=UNHEX(:o) ORDER BY expires_on,id');$s->execute(['o'=>$o]);return array_map(fn($r)=>$this->camel($r),$s->fetchAll());}
    /** @return array<string,mixed> */ private function registration(string$o,string$id):array{$s=$this->pdo->prepare('SELECT *,LOWER(HEX(id)) id FROM practice_registration_renewals WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)');$s->execute(['o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new PracticeException('practice_registration_not_found');return$this->camel($r);}
    /** @return list<array<string,mixed>> */ private function templates(string$o,string$u):array{$role=$this->membershipRole($o,$u);$s=$this->pdo->prepare('SELECT *,LOWER(HEX(id)) id,LOWER(HEX(template_key)) template_key FROM practice_templates WHERE organisation_id=UNHEX(:o) ORDER BY name,version');$s->execute(['o'=>$o]);$out=[];foreach($s->fetchAll()as$r){$roles=$this->decode($r['allowed_roles']);if(!in_array($role,$roles,true)&&!in_array($role,['owner','administrator','admin'],true))continue;$r['allowed_roles']=$roles;$out[]=$this->camel($r);}return$out;}
    /** @return array<string,mixed> */ private function templateRow(string$o,string$u,string$id):array{$role=$this->membershipRole($o,$u);$s=$this->pdo->prepare('SELECT *,LOWER(HEX(id)) id,LOWER(HEX(template_key)) template_key FROM practice_templates WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)');$s->execute(['o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new PracticeException('practice_template_not_found');$roles=$this->decode($r['allowed_roles']);if(!in_array($role,$roles,true)&&!in_array($role,['owner','administrator','admin'],true))throw new PracticeException('practice_template_forbidden');return$r;}
    /** @return array<string,mixed> */ private function scoped(string$table,string$o,string$u,string$id,string$error):array{$s=$this->pdo->prepare("SELECT t.*,LOWER(HEX(t.project_id)) project_id FROM $table t JOIN organisation_memberships m ON m.organisation_id=t.organisation_id AND m.user_id=UNHEX(:u) AND m.status='active' WHERE t.organisation_id=UNHEX(:o) AND t.id=UNHEX(:id)");$s->execute(['u'=>$u,'o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new PracticeException($error);foreach(['user_id','assigned_user_id','mentor_user_id','candidate_user_id']as$c)if(isset($r[$c])&&is_string($r[$c])&&strlen($r[$c])===16)$r[$c]=bin2hex($r[$c]);return$r;}
    private function assertProject(string$o,string$u,string$p):void{$s=$this->pdo->prepare("SELECT 1 FROM projects p JOIN organisation_memberships m ON m.organisation_id=p.organisation_id AND m.user_id=UNHEX(:u) AND m.status='active' WHERE p.organisation_id=UNHEX(:o) AND p.id=UNHEX(:p)");$s->execute(['u'=>$u,'o'=>$o,'p'=>$p]);if($s->fetchColumn()===false)throw new PracticeException('practice_project_not_found');}
    private function assertMembership(string$o,string$u):void{$this->membershipRole($o,$u);}
    private function membershipRole(string$o,string$u):string{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);$role=$s->fetchColumn();if(!is_string($role))throw new PracticeException('practice_membership_required');return$role;}
    private function assertMember(string$o,string$u):void{$this->membershipRole($o,$u);}
    private function firstProject(string$o):string{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) FROM projects WHERE organisation_id=UNHEX(:o) ORDER BY created_at,id LIMIT 1');$s->execute(['o'=>$o]);$p=$s->fetchColumn();if(!is_string($p))throw new PracticeException('practice_project_not_found');return$p;}
    private function assertOwned(string$table,string$o,string$p,string$id,string$error):void{$s=$this->pdo->prepare("SELECT 1 FROM $table WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);if($s->fetchColumn()===false)throw new PracticeException($error);}
    private function governor(string$role):void{if(!in_array($role,['owner','administrator','admin'],true))throw new PracticeException('practice_review_forbidden');}
    private function professional(string$o,string$u,string$role,string$p,string$mentor,string$candidate):void{if($u===$candidate)throw new PracticeException('practice_registered_professional_required');if(in_array($role,['owner','administrator','admin'],true))return;if($u!==$mentor)throw new PracticeException('practice_registered_professional_required');$s=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND user_id=UNHEX(:u) AND status='active' AND discipline IN ('architect','engineer','quantity_surveyor')");$s->execute(['o'=>$o,'p'=>$p,'u'=>$u]);if($s->fetchColumn()===false)throw new PracticeException('practice_registered_professional_required');}
    /** @return array<string,mixed> */ private function camel(array$r):array{$out=[];foreach($r as$key=>$v){if(in_array($key,['organisation_id','project_id'],true))continue;$name=preg_replace_callback('/_([a-z])/',static fn($m)=>strtoupper($m[1]),(string)$key);if(is_string($v)&&strlen($v)===16&&($key==='id'||str_ends_with((string)$key,'_id')||str_ends_with((string)$key,'_by')))$v=bin2hex($v);if(in_array($key,['over_allocated','billable','expenses_ready','disbursements_ready','creates_invoice','moves_money','verification_guaranteed'],true))$v=(bool)$v;if(in_array($key,['version','probability_percent','forecast_value_cents','weighted_value_cents','sla_hours','allocated_minutes','capacity_minutes','minutes','approved_billable_minutes'],true))$v=(int)$v;$out[$name]=$v;}return$out;}
    /** @template T @param callable():T$f @return T */ private function transaction(callable$f):mixed{$this->pdo->beginTransaction();try{$v=$f();$this->pdo->commit();return$v;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
    /** @param array<string,mixed>$input */ private function confirmed(array$input):void{if(($input['humanConfirmed']??false)!==true)throw new PracticeException('practice_human_confirmation_required');}
    private function text(mixed$v,int$max,string$error):string{if(!is_string($v)||trim($v)===''||mb_strlen(trim($v))>$max)throw new PracticeException($error);return trim($v);}
    /** @param list<string>$choices */ private function choice(mixed$v,array$choices,string$error):string{if(!is_string($v)||!in_array($v,$choices,true))throw new PracticeException($error);return$v;}
    private function integer(mixed$v,int$min,int$max,string$error):int{if(!is_int($v)&&!(is_string($v)&&preg_match('/\A\d+\z/',$v)===1))throw new PracticeException($error);$n=(int)$v;if($n<$min||$n>$max)throw new PracticeException($error);return$n;}
    private function decimalHours(mixed$v,string$error):int{if(!is_int($v)&&!is_float($v)&&!(is_string($v)&&is_numeric($v)))throw new PracticeException($error);$n=(float)$v;if($n<0||$n>10000)throw new PracticeException($error);return(int)round($n*60);}
    private function decimal(mixed$v,string$error):float{if(!is_int($v)&&!is_float($v)&&!(is_string($v)&&is_numeric($v)))throw new PracticeException($error);$n=(float)$v;if($n<0||$n>100000)throw new PracticeException($error);return$n;}
    private function id(mixed$v,string$error):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new PracticeException($error);return strtolower($v);}
    private function nullableId(mixed$v,string$error):?string{return$v===null||$v===''?null:$this->id($v,$error);}
    private function date(mixed$v,string$error):string{if(!is_string($v)||DateTimeImmutable::createFromFormat('!Y-m-d',$v)?->format('Y-m-d')!==$v)throw new PracticeException($error);return$v;}
    private function nullableDate(mixed$v,string$error):?string{return$v===null||$v===''?null:$this->date($v,$error);}
    private function dateTime(mixed$v,string$error):string{if(!is_string($v))throw new PracticeException($error);try{$d=new DateTimeImmutable($v);}catch(Throwable){throw new PracticeException($error);}return$d->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}
    /** @return list<string> */ private function strings(mixed$v,int$max,string$error):array{if(!is_array($v)||$v===[]||count($v)>$max)throw new PracticeException($error);$out=[];foreach($v as$x){if(!is_string($x)||trim($x)===''||mb_strlen(trim($x))>160)throw new PracticeException($error);$out[]=trim($x);}return array_values(array_unique($out));}
    /** @return list<string> */ private function roles(mixed$v):array{$roles=$this->strings($v,4,'practice_template_roles_invalid');foreach($roles as$role)if(!in_array($role,['owner','admin','member','viewer'],true))throw new PracticeException('practice_template_roles_invalid');return$roles;}
    private function json(mixed$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);}
    /** @return array<mixed> */ private function decode(mixed$v):array{if(!is_string($v))return[];$d=json_decode($v,true,512,JSON_THROW_ON_ERROR);return is_array($d)?$d:[];}
